// Advance every IDENTITY SEQUENCE that has fallen BEHIND its table, so the
// next insert from the app stops dying on duplicate key.
//
// WHAT THIS FIXES, plainly: "i cant create project". See
// scripts/check-sequence-drift.mjs for the full mechanism — in one line, every
// id column here is `GENERATED BY DEFAULT AS IDENTITY`, which lets a bulk copy
// write its own ids without advancing the sequence, silently, and the next
// organic insert then collides with a row that already exists.
//
// RE-RUN: safe and idempotent. setval is computed from max(id) at the moment it
// runs, so a second run with no drift sets each sequence to the value it
// already holds and reports zero repairs. Never destructive: it only ever moves
// a sequence FORWARD to max(id), never backward, and it touches no table row.
//
// REVERSAL: none is needed and none is offered. The previous `last_value` was a
// number the table had already used, so restoring it would restore the bug.
// Sequence gaps are free and permanent by design; nothing reads a sequence
// position as data.
//
// SCOPE: sequences only. It does NOT delete the empty projects a failed New
// Project click leaves behind — the detector lists them, and deleting a project
// row is a judgement call for a person, not for a repair script.
import { readFileSync } from "node:fs";
import postgres from "postgres";

const MODE = process.env.MODE ?? "plan";
const CONFIRM = process.env.CONFIRM ?? "";
const CONFIRM_PHRASE = "repair-sequences";

// Same resolution order as pg-migrate.mjs: env wins so CI needs no .dev.vars.
function resolveUrl() {
  if (process.env.DATABASE_URL) return process.env.DATABASE_URL;
  try {
    return readFileSync(".dev.vars", "utf8").match(/DATABASE_URL="([^"]+)"/)?.[1];
  } catch {
    return undefined;
  }
}

const url = resolveUrl();
if (!url) {
  console.error("DATABASE_URL not set and no .dev.vars — cannot reach the database.");
  process.exit(1);
}

if (MODE === "apply" && CONFIRM !== CONFIRM_PHRASE) {
  console.error(`MODE=apply requires CONFIRM=${CONFIRM_PHRASE}. Refusing to write.`);
  process.exit(1);
}

// Owning column resolved through pg_depend rather than by guessing the
// `<table>_<col>_seq` name: project_finance's sequence is attached to
// `project_id`, not to an `id`, so a name-shaped guess misses it.
const OWNED = `
  SELECT c.relname AS seq, dc.relname AS tbl, a.attname AS col
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'
    JOIN pg_depend d ON d.objid = c.oid AND d.deptype IN ('a', 'i')
    JOIN pg_class dc ON dc.oid = d.refobjid
    JOIN pg_attribute a ON a.attrelid = dc.oid AND a.attnum = d.refobjsubid
   WHERE c.relkind = 'S'
   ORDER BY dc.relname, a.attname`;

// Table / column names come from pg_catalog, never from a caller, so they are
// already valid identifiers. Quote them anyway: a lowercase-looking name is not
// proof, and `unsafe()` does no quoting of its own.
const q = (id) => `"${String(id).replace(/"/g, '""')}"`;
const lit = (s) => `'${String(s).replace(/'/g, "''")}'`;

// A sequence AHEAD of max(id) is correct — gaps are free and every rolled-back
// insert leaves one. Only BEHIND is the fault.
async function findDrift(conn) {
  const owned = await conn.unsafe(OWNED);
  const behind = [];
  for (const row of owned) {
    const [{ max_id }] = await conn.unsafe(
      `SELECT COALESCE(max(${q(row.col)}), 0)::bigint AS max_id FROM public.${q(row.tbl)}`
    );
    const [{ last_value }] = await conn.unsafe(
      `SELECT last_value::bigint AS last_value FROM public.${q(row.seq)}`
    );
    if (BigInt(max_id) - BigInt(last_value) > 0n) {
      behind.push({ ...row, max_id: String(max_id), last_value: String(last_value) });
    }
  }
  return { scanned: owned.length, behind };
}

const sql = postgres(url, { max: 1, idle_timeout: 5, connect_timeout: 15 });
let repaired = [];

try {
  const { scanned, behind } = await findDrift(sql);
  console.log(`MODE=${MODE}. Scanned ${scanned} public sequences.`);

  if (behind.length === 0) {
    console.log("Nothing is behind its table. No repair needed.");
    await sql.end({ timeout: 5 });
    process.exit(0);
  }

  for (const b of behind) {
    console.log(
      `${MODE === "apply" ? "REPAIR" : "PLAN  "} ${b.tbl}.${b.col}: sequence ${b.last_value} -> ${b.max_id}`
    );
  }

  if (MODE !== "apply") {
    console.log("");
    console.log(`Plan only. Nothing was written. To apply:`);
    console.log(`  MODE=apply CONFIRM=${CONFIRM_PHRASE} node scripts/repair-sequence-drift.mjs`);
    await sql.end({ timeout: 5 });
    process.exit(0);
  }

  for (const b of behind) {
    // setval reads max() inside the same statement, so a row inserted between
    // the plan above and this write is still covered.
    await sql.unsafe(
      `SELECT setval(pg_get_serial_sequence(${lit(`public.${b.tbl}`)}, ${lit(b.col)}),
                     (SELECT max(${q(b.col)}) FROM public.${q(b.tbl)}))`
    );
    repaired.push(b);
  }
  console.log(`Wrote ${repaired.length} setval(s).`);
} finally {
  await sql.end({ timeout: 5 });
}

if (MODE !== "apply") process.exit(0);

// VERIFY ON A FRESH CONNECTION, and assert the SHAPE rather than a count. A
// count of setvals written would report success for a sequence that is still
// behind — the shape that matters is "no sequence is behind any more", plus a
// live INSERT actually receiving a free id, which is the thing the app does and
// the only thing the owner cares about.
const verify = postgres(url, { max: 1, idle_timeout: 5, connect_timeout: 15 });
try {
  const { behind } = await findDrift(verify);
  if (behind.length > 0) {
    console.error("");
    console.error(`VERIFY FAILED: ${behind.length} sequence(s) STILL behind after the repair:`);
    for (const b of behind) console.error(`  ${b.tbl}.${b.col} at ${b.last_value}, table at ${b.max_id}`);
    process.exit(1);
  }

  // Shape check on the pair that actually breaks New Project: draw a real id
  // from each sequence and confirm the table does not already hold it. Rolled
  // back, so it inserts nothing; the drawn ids are consumed, which is a gap and
  // therefore free.
  for (const [tbl, col] of [
    ["project_checklist_sections", "id"],
    ["project_checklist", "id"],
  ]) {
    const [{ next_id, taken }] = await verify.unsafe(`
      WITH n AS (SELECT nextval(pg_get_serial_sequence(${lit(`public.${tbl}`)}, ${lit(col)})) AS v)
      SELECT n.v AS next_id,
             EXISTS (SELECT 1 FROM public.${q(tbl)} t WHERE t.${q(col)} = n.v) AS taken
        FROM n`);
    if (taken) {
      console.error("");
      console.error(`VERIFY FAILED: ${tbl} would be handed id ${next_id}, which is already used.`);
      process.exit(1);
    }
    console.log(`VERIFIED ${tbl}: next id ${next_id} is free.`);
  }

  console.log("");
  console.log(`VERIFIED: no sequence is behind its table. Repaired ${repaired.length}.`);
} finally {
  await verify.end({ timeout: 5 });
}
